import json,fitz
qs=[]
def q(n,page,text,opts,ans,topic,exps,key,figure=None,ft=None):
 d=dict(n=n,year=2025,page=page,text=text,options=opts.split('|'),answer=ans,topic=topic,explanations=exps.split('|'),keypoint=key)
 if figure:d['figure']='sources/q%d.png'%n
 if ft:d['figureText']=ft
 qs.append(d)
q(1,3,'JIS Q 21500:2018（プロジェクトマネジメントの手引）によれば，プロジェクトガバナンスを維持する責任は誰にあるか。','プロジェクトの管理面でプロジェクトマネージャを支援するプロジェクトマネジメントチーム|プロジェクトの計画から終結までのプロセスを指揮するプロジェクトマネージャ|プロジェクトの要求事項を明確にし，プロジェクトの成果を享受する顧客|プロジェクトを許可し，経営的決定を下すプロジェクトスポンサ，又は上級レベルでの指導を行うプロジェクト運営委員会',3,'ガバナンス','管理の支援を担うチームであり，ガバナンス維持の責任主体とは区別する。|PMは日々のプロジェクトの指揮を担うが，経営上の統治の責任主体とは異なる。|顧客は要求と成果の受益に関わる立場。ガバナンスの維持を担うとは限らない。|正解。スポンサ又は運営委員会が，組織の方針との整合や意思決定・監督の仕組みを維持する。','プロジェクトを運営するPMと，経営的な統治を担うスポンサを区別する。')
q(2,3,'JIS Q 21500:2018（プロジェクトマネジメントの手引）において，“変更要求”によって“管理のプロセス群”に作用し，その結果である“承認された変更”によって“管理のプロセス群”から作用されるプロセス群がある。図中の a に入れる適切な字句はどれか。','計画のプロセス群|実行のプロセス群|終結のプロセス群|立ち上げのプロセス群',1,'ガバナンス','計画を策定するプロセス群。図の変更要求と承認された変更の往復の相手は実行。|正解。実行から変更要求が出され，管理で承認された変更が実行へ戻り反映される。|プロジェクトやフェーズを正式に完了させるためのプロセス群。|プロジェクトやフェーズの開始を認可するためのプロセス群。','変更要求を管理し，承認済みの変更を実行に反映する。',True,'a → 管理のプロセス群：変更要求\n管理のプロセス群 → a：承認された変更')
q(3,4,'プロジェクトの成果を予測する際に用いる回帰分析の説明はどれか。','アウトプットとこれに対応した一連のインプット変数との関係について多数のデータを用いて分析し，統計学的関係を明らかにする。|差異，欠陥，又はリスクを引き起こす根源的な理由を明らかにする。|ベースラインと実際のパフォーマンスについて，違いが生じた原因と，違いの度合いを判定する。|予算，コスト，スケジュール，又はスコープのパラメータとベースラインとの差異を判定し，これに基づいて将来のある時点におけるパラメータのベースラインからの差異を予測する。',0,'コスト','正解。説明変数（入力）と目的変数（出力）の統計的な関係をモデル化して予測に使う。|根本原因分析の説明。変数間の統計的関係を求める回帰分析とは異なる。|差異分析の説明。計画と実績の差及びその原因を調べる。|傾向分析に当たる説明。実績の傾向を使って将来の差異を予測する。','回帰分析は「複数のデータから入力と出力の関係を求める」。')
q(4,4,'プロジェクトマネジメントにおいて，スコープクリープが発生する原因となり得る事例はどれか。','スコープの大幅な拡大が必要となったので，変更要求の承認を得た。|設計中の機能を拡充するための軽微な変更要求と判断したので，コストや工数を見積もることなく，設計作業を推進した。|プロジェクト初期に定義した成果物及び作業を変更する必要はないが，作業工数の見積りが過小であった。|変更要求によるスコープの拡大を変更管理委員会に諮ったが，承認されなかった。',1,'スコープ','正式な変更管理で承認されている。大幅な拡大であることだけではスコープクリープにはならない。|正解。影響評価や管理を省略して機能を増やすと，コストやスケジュールの調整を伴わないスコープ拡大につながる。|工数見積りの誤りであり，スコープ自体は変わっていない。|変更を審査して拒否している。拒否された変更を勝手に実施したとの記述はない。','小さな変更でも影響評価と承認を省かない。')
q(5,5,'ホーソン効果の，システム開発プロジェクトにおける例として，適切なものはどれか。','開発サイクルごとの成果物のレビューで，ある開発チームの成果物がプロダクトオーナーに注目されたことによって，その開発チームの士気が上がり，その後の生産性が向上した。|開発チーム別の進捗報告会で，遅れを報告したチームは優秀なチームだったので，遅れは挽回可能であるという報告を信用したが，次の進捗報告で遅れが拡大した。|結合テストで3件の誤りが検出され，そのうちの2件の誤りが同一のモジュールに起因していたので，残りの1件もそのモジュールに起因していると思い込んで調査したが，そのモジュールから誤りは検出できなかった。|全ての利用者が満足する UI を開発するという達成困難な目標を開発チームに対して設定したので，開発チームの士気が下がり，その後の生産性が低下した。',0,'人・組織','正解。周囲から注目されているという意識が，行動や生産性を変える効果を表している。|優秀だという評価によって個別の報告まで好意的に判断しており，ハロー効果に近い。|先に得た情報に引きずられた思い込みであり，注目されることによる行動変化ではない。|達成困難な目標による意欲低下であり，ホーソン効果の例ではない。','ホーソン効果は「注目されることで行動が変わる」。')
q(6,5,'図は，実施する三つのアクティビティについて，プレシデンスダイアグラム法を用いて，依存関係及び必要な作業日数を示したものである。全ての作業を完了するための所要日数は最少で何日か。','11|12|13|14',1,'スケジュール','Bは11日目相当で終わるが，Cが完了しておらず全体の所要日数ではない。|正解。開始時点を0とするとAは6で終了。Bは2日リードなので4で開始し11で終了。CはB開始から3日後の7で開始し12で終了。|AとBを単純に直列加算した6＋7に相当し，リードを反映していない。|依存関係から求めた最早完了12を超え，最少日数ではない。','リードは先行できる時間，ラグは待つ時間。終了時刻はA=6，B=11，C=12。',True,'A：6日 → B：7日（終了−開始関係，リード2日）\nB → C：5日（開始−開始関係，ラグ3日）')
q(7,6,'図1に示すプロジェクト活動は，作業Cの終了がこの計画から2日遅れたので，このままでは当初に計画した総所要日数で終了できなくなった。\n\n作業を見直したところ，作業Iは作業Gの全てが完了していなくても開始できることが分かったので，ファストトラッキングを適用して，図2に示すように計画を変更した。計画変更後の総所要日数は当初計画と比べてどのように変化するか。','4日減少する|2日減少する|1日増加する|2日増加する',2,'スケジュール','並行化の短縮効果だけで判断してはいけない。Cの遅延と他の経路の長さを考慮する。|GとIの経路は短縮されるが，変更後はFとHを通る経路が全体を決める。|正解。当初はA−C−G−I−J＝4＋10＋7＋4＋8＝33日。変更後はA−C−F−H−J＝4＋12＋4＋6＋8＝34日で，1日増加する。|Cの2日遅延だけを足すと誤る。並行化による経路の変更を反映する必要がある。','ファストトラッキング後はクリティカルパスが変わることがある。',True,'図1：A=4，B=5，C=10，D=4，E=2，F=4，G=7，H=6，I=4，J=8。A後にB/C，B後にD/E，CとDの合流後にF/G，EとFの合流後にH，G後にI，HとIの合流後にJ。\n図2：C=12に変更。GをG1=2とG2=5に分割し，G1後にIを開始，G2とIとHの完了後にJ。その他は図1と同じ。')
q(8,7,'プロジェクトのスケジュール管理で使用する“クリティカルチェーン法”の実施例はどれか。','限りある資源とプロジェクトの不確実性とに対応するために，合流バッファとプロジェクトバッファとを設ける。|クリティカルパス上の作業に，生産性を向上させるための開発ツールを導入する。|クリティカルパス上の作業に，要員を追加投入する。|クリティカルパス上の先行作業が終了する前に後続作業に着手し，双方の作業を並行して実施する。',0,'スケジュール','正解。資源制約を考慮し，個々の作業ではなく合流点やプロジェクト終端のバッファで不確実性を吸収する。|作業効率を改善する施策だが，バッファ管理を特徴とするクリティカルチェーン法の説明ではない。|追加資源で期間を短縮するクラッシングの例。|作業を並行化するファストトラッキングの例。','クリティカルチェーン＝資源制約＋バッファ。')
q(9,7,'COCOMOには，システム開発の工数を見積もる式の一つとして次式がある。\n開発工数＝3.0×（開発規模）¹·¹²\n\nこの式を基に，開発規模と開発生産性（開発規模÷開発工数）の関係を表したグラフはどれか。ここで，開発工数の単位は人月，開発規模の単位はキロ行とする。','アのグラフ|イのグラフ|ウのグラフ|エのグラフ',3,'コスト','右上がりなので，規模が増すと生産性が低下するこの式には合わない。|右上がりで増加が加速しており，式の関係と逆。|右下がりではあるが，低下が急になる形が式と異なる。|正解。規模をSとすると生産性＝S÷(3S^1.12)＝(1/3)S^-0.12。Sが増えるほど下がり，低下の傾きは緩やかになる。','生産性は工数の逆数ではなく「規模÷工数」。式を簡約して形を見る。',True,'グラフの軸は全て，横軸：開発規模，縦軸：開発生産性。選択肢は原本の図。テキスト表現：ア＝右上がりで傾きが緩やかになる，イ＝右上がりで傾きが急になる，ウ＝右下がりで傾きが急になる，エ＝右下がりで傾きが緩やかになる。')
q(10,8,'JIS Q 21500:2018（プロジェクトマネジメントの手引）によれば，プロセス“リスクの特定”及びプロセス“リスクの評価”は，どのプロセス群に属するか。','管理|計画|実行|終結',1,'リスク','リスクの管理など，状況を監視して必要な措置を取る活動に対応する。|正解。特定したリスクの発生可能性や影響等を評価し，対応を計画するための活動なので計画のプロセス群に属する。|リスクへの対応を実施する段階と，特定・評価の位置付けを混同しない。|プロジェクトを正式に完了するためのプロセス群。','リスクの特定・評価は計画。実際には反復しても，分類上の所属は計画。')
q(11,8,'表は，プロジェクトのコミュニケーション計画において作成した“会議体の一覧”である。5W1Hの指針に照らしたときに，不足している項目はどれか。','会議室の利用料|重要度|主催者及び参加者|成果物',2,'コミュニケーション','費用（How much）に当たり，5W1Hの必須要素ではない。|優先度を表すが，5W1Hの不足を直接埋めるものではない。|正解。目的＝Why，内容＝What，開催日＝When，形式＝How，場所＝Whereはあるが，Whoに当たる主催者・参加者がない。|成果物はWhatに関連するが，この一覧で欠けているのはWho。','会議の5W1Hでは「誰が主催し，誰が参加するか」を忘れない。',True,'名称｜目的｜内容｜開催日｜形式｜場所\nプロジェクト内定例報告会｜プロジェクトチーム内での情報共有｜プロジェクトの進捗と課題の状況を確認する｜毎週木曜日｜対面｜自社会議室\n顧客定例報告会｜顧客との情報共有｜プロジェクトの進捗と課題の状況を報告する｜毎週金曜日｜Web｜自社会議室，顧客会議室\nステアリングコミッティ｜プロジェクトの重要な意思決定｜重要な課題や問題を報告し，方針を決定する｜意思決定が必要なとき｜対面｜自社役員会議室')
q(12,9,'JIS Q 21500:2018（プロジェクトマネジメントの手引）によれば，プロセス“コミュニケーションの計画”の目的はどれか。','プロジェクトに影響されるか，又は影響を及ぼす個人，集団又は組織を明らかにし，その利害及び関係に関連する情報を文書化すること|プロジェクトのステークホルダに対し，要求した情報を利用可能にすること及び情報に対する予期せぬ具体的な要求に対応すること|プロジェクトのステークホルダのコミュニケーションニーズを確実に満足し，コミュニケーションの問題が発生したときにそれを解決すること|プロジェクトのステークホルダの情報及びコミュニケーションのニーズを決定すること',3,'コミュニケーション','ステークホルダの特定に当たる。誰が関係者かを明らかにする活動。|情報の配布に当たる。必要な情報を実際に利用可能にする活動。|コミュニケーションの管理に当たる。ニーズの充足を確認し，問題を解消する活動。|正解。誰がどんな情報を必要とするかを決め，伝達方法等を計画するための出発点となる。','計画＝ニーズを決める，配布＝情報を届ける，管理＝問題を解消する。')
q(13,9,'アジャイル開発プロセスにおいて，Bill Wake が提案した“INVEST”と呼ばれる六つの観点を用いて行うことはどれか。','効率よくアクティビティ図を作成する。|コード化できるレベルまで詳細化されたデータフロー図を作成する。|再利用しやすいソフトウェアパターンとなっているかどうかを評価する。|質の高いユーザーストーリーとなっているかどうかを評価する。',3,'開発・品質','INVESTはアクティビティ図を作成する手法ではない。|DFDの詳細化を評価する観点ではない。|ソフトウェアパターンの再利用性評価を目的とするものではない。|正解。Independent（独立），Negotiable（交渉可能），Valuable（価値がある），Estimable（見積可能），Small（小さい），Testable（テスト可能）の6観点でユーザーストーリーを評価する。','INVESTは良いユーザーストーリーのチェック観点。')
json.dump(qs,open('/workspace/sites/pm-a2-study/first.json','w'),ensure_ascii=False,indent=2)
p=fitz.open('/workspace/sites/pm-a2-study/dist/sources/2025-questions.pdf')
for n,page,rect in [(2,3,(180,390,405,515)),(6,5,(145,435,425,625)),(7,6,(50,110,475,480)),(9,7,(70,410,410,620)),(11,8,(65,250,470,410))]:
 # Coordinates based on page proportions: use screenshot scale for precise crops below
 pass
# Crop using pixel coordinates from 1.5x render (original page is 516 x 729 approx).
for n,page,box in [(2,3,(280,580,550,775)),(6,5,(220,670,610,940)),(7,6,(90,175,680,700)),(9,7,(110,610,580,910)),(11,8,(100,370,710,605))]:
 pg=p[page-1]; pg.get_pixmap(matrix=fitz.Matrix(2,2),clip=fitz.Rect(*(v/1.5 for v in box))).save('/workspace/sites/pm-a2-study/dist/sources/q%d.png'%n)
